// msg.payload = change record from abraflexi-webhook
const data = msg.payload;
const metrics = data.metrics || {};
const cycles  = metrics.cycles || 0;
const SPIKE   = 1.0;

// Aggregate pass_N_op_dir raw timing values
const agg = {};
for (const [key, rawVal] of Object.entries(metrics)) {
    if (key === 'cycles' || key === 'delay') continue;
    const m = key.match(/^pass_\d+_(.+)_(read|write)$/);
    if (!m) continue;
    const v = parseFloat(rawVal);
    if (isNaN(v)) continue;
    const k = `${m[1]}:${m[2]}`;
    if (!agg[k]) agg[k] = {op: m[1], dir: m[2], vals: []};
    agg[k].vals.push(v);
}

const rows = Object.values(agg)
    .map(({op, dir, vals}) => ({
        op, dir,
        avg:    vals.reduce((s, v) => s + v, 0) / vals.length,
        max:    Math.max(...vals),
        spikes: vals.filter(v => v >= SPIKE).length
    }))
    .sort((a, b) => a.op.localeCompare(b.op) || a.dir.localeCompare(b.dir));

const SEP = '+' + [16,7,8,8,11].map(n => '-'.repeat(n)).join('+') + '+';
let table = `AbraFlexi Benchmark — ${cycles} cycles, delay ${metrics.delay||0}s\n`;
table += `Status: ${(data.status||'?').toUpperCase()}  |  ${data['@timestamp']||data.timestamp||""}\n\n`;
table += SEP + '\n';
table += '| Operation      | Dir   | Avg    | Max    | 1s spikes |\n';
table += SEP + '\n';
for (const r of rows) {
    table += `| ${r.op.replace(/_/g,' ').padEnd(14)} | ${r.dir.padEnd(5)} | `
           + `${(r.avg.toFixed(3)+'s').padEnd(6)} | ${(r.max.toFixed(3)+'s').padEnd(6)} | `
           + `${String(r.spikes).padEnd(9)} |\n`
           + SEP + '\n';
}

const ts = data['@timestamp'] || data.timestamp || '';
node.status({
    fill:  data.status === 'success' ? 'green' : (data.status === 'error' ? 'red' : 'yellow'),
    shape: 'dot',
    text:  `${cycles} cycles @ ${new Date(ts).toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`
});

// Pass the benchmarked record ID to the evidence-type switch.
// The benchmark tool sets @evidence and id on the change record.
const evidence = data['@evidence'] || '';
const id       = String(data.id || '').trim();
const dispatch = evidence && id
    ? {...msg, payload: {id}, topic: evidence}
    : null;

return [{...msg, payload: table}, dispatch];
